{
"predictors": [
{
"name": "Investment to Capital Ratio",
"construction": "Compustat's annual capital expenditures divided by total assets, both at fiscal year-end.",
"rationale": "Greater investment could imply management's belief in future growth opportunities.",
"higher_returns_for": "High values of the measure"
},
{
"name": "R&D Spend to Sales Ratio",
"construction": "Compustat's annual R&D expense divided by annual sales revenue, both at fiscal year-end.",
"rationale": "Firms spending more on R&D may have promising future growth prospects.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Debt Maturity Structure",
"construction": "CRSP's long-term debt divided by total debt, both at fiscal year-end.",
"rationale": "A firm's maturity structure can signal its credit risk.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Advertising to Sales Ratio",
"construction": "Compustat's annual advertising expense divided by annual sales revenue, both at fiscal year-end.",
"rationale": "Higher advertising spend could suggest a firm's confidence in its products.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Durable Asset Ratio",
"construction": "Compustat's property, plant & equipment divided by total assets, both at fiscal year-end.",
"rationale": "Firms with more durable assets might be more resilient to downturns.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Dividend Payout Frequency",
"construction": "Number of times dividends are paid during the fiscal year, sourced from CRSP.",
"rationale": "Frequent payouts could signal management's confidence in consistent cash flows.",
"higher_returns_for": "High values of the measure"
},
{
"name": "CEO Tenure",
"construction": "Number of years the current CEO has been in position, sourced from proxy statements.",
"rationale": "Longer CEO tenure might indicate stable management and strategic focus.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Revenue Concentration",
"construction": "Herfindahl index of sales across different business segments, sourced from Compustat Segment data.",
"rationale": "High concentration might indicate a firm's competitiveness in its main operations.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Employee Productivity",
"construction": "Annual sales revenue divided by the number of employees, both sourced from Compustat at fiscal year-end.",
"rationale": "Higher productivity could reflect efficient operations and superior human capital management.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Insider Trading Volume",
"construction": "Number of shares traded by insiders during the fiscal year, sourced from SEC Form 4 filings.",
"rationale": "Insider trading can provide signals about the firm's future prospects.",
"higher_returns_for": "High values of the measure"
}
]
}
